/** Host-native workflow instructions generated by `stetra init`. */

export type HostAdapter = 'codex' | 'claude';

export const HOST_WORKFLOW_REFERENCES = [
  'change', 'delivery', 'challenge', 'handoff', 'recovery',
] as const;
export type HostWorkflowReference = typeof HOST_WORKFLOW_REFERENCES[number];

const CHALLENGER_INSTRUCTIONS = `You are the Stetra Independent Challenger for one bounded Evidence Obligation.

Use only the current Challenge Execution Request and its exact Challenge
Execution Packet. When the dispatch prompt contains **Stetra task** and
**Challenge request**, run its exact context-retrieval command first. Continue
only when the returned hostAction is **perform-independent-challenge** and its
requestId matches the dispatch prompt. Use that action's packet; do not scan
other runs or infer a current task. The packet is complete for this bounded
role: do not load the general Stetra skill or its workflow reference pages. Inspect the named target,
exact Human-event basis, current repository, and Runtime evidence, then actively
test the frozen failure hypothesis. Do not broaden the task. If the packet is
structurally insufficient, report partial or unknown instead of recovering
generic workflow context.

The target worktree is read-only. A trusted Host may place the exact bound
snapshot in an isolated writable workspace so repository tests can create or
modify their normal fixtures and caches there. Do not author implementation or
assertion edits in either workspace. Do not install, commit, spawn another
agent, choose an implementation route, or make the Human adoption decision. If
no isolated workspace is available and inspection cannot support the requested
observation, return partial or unknown and name that limitation.
A supported outcome must contain no counterEvidence. If any counter-evidence
remains, use partial, contradicted, or unknown according to the observation.
Explicitly assess whether the selected evidence covers the whole bounded
conclusion. Preserve every uncovered aspect in evidenceCoverage.gaps; an
insufficient assessment cannot produce a supported outcome.

Return exactly one JSON Challenge Round matching the prefilled
challengeExecutionPacket.draft. Fill every result's open judgment fields. Do
not wrap it in Markdown or add prose. Cite only exact IDs present in that case.
Never
author request identity, context identity, independence, or a Host receipt; the
controlling Host owns those fields.`;

export function renderCodexChallengerAgent(): string {
  return `name = "stetra-challenger"
description = "Independently challenge one Stetra evidence round in a fresh read-only context."
sandbox_mode = "read-only"
developer_instructions = """
${CHALLENGER_INSTRUCTIONS}
"""
`;
}

export function renderClaudeChallengerAgent(): string {
  return `---
name: stetra-challenger
description: Independently challenge one Stetra evidence obligation in a fresh read-only context.
tools: Read, Grep, Glob
permissionMode: plan
maxTurns: 20
---

${CHALLENGER_INSTRUCTIONS}
`;
}

export function renderHostSkill(adapter: HostAdapter): string {
  const host = adapter === 'codex' ? 'Codex' : 'Claude Code';
  return `---
name: stetra
description: Preserve developer understanding and decision authority while a coding Agent delivers an inspectable change.
---

# Stetra

Use this for a production change from exact intent to informed adoption. ${host}
owns engineering; the developer owns goals, long-lived tradeoffs, exceptions,
and adoption;
Runtime owns only facts it collects.

Read [references/change.md](references/change.md) before prepare, then follow
each **hostAction**. Load its named reference; do not reread an unchanged page
in one context. Fill the projected **draft** by its requirements and send it
through the exact **inputBinding**. Exact
developer events are Human authority; interpretations are Agent judgment.

Before responding, run **stetra change guard-final . --task <task-id> --json**.
If its exact prior Action remains in context, pass
**--known-action-fingerprint <sha256>**; **actionUnchanged** means reuse it.
Obey **disposition**. This skill does not claim native Host enforcement.

**hostAction.developerDecisionBrief.primary** owns the concise final cognitive
handoff. Its prose-facing surface intentionally omits opaque protocol IDs;
**details** retains every exact reference for inspection and continuation.
Preserve every decision-changing primary item, contrast intended and actual
meaning, state adoption is pending, ask for the decision, and stop. Execute
**decisionContinuation** only after a new developer message supplies it.

Keep Human authority, Agent judgment, Runtime facts, and adoption separate.
Passing is not adoption. Never invent facts or hide adoption-changing surfaces;
preserve exact paths, IDs, enums, commands, numeric facts, and quoted events.
`;
}

export function renderHostWorkflowReference(
  _adapter: HostAdapter,
  workflow: HostWorkflowReference,
): string {
  return WORKFLOW_REFERENCES[workflow];
}

export function renderHostPointerBlock(
  adapter: HostAdapter,
  markers: { start: string; end: string },
): string {
  const skillPath = adapter === 'codex'
    ? '.agents/skills/stetra/SKILL.md'
    : '.claude/skills/stetra/SKILL.md';
  return `${markers.start}
For production coding changes, read and follow [the generated Stetra skill](${skillPath}).
${markers.end}`;
}

